import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Search Connector","description":"","frontmatter":{"epic":3,"title":"Search Connector","status":"✅ Done","scope":"mobile","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/mobile/search-connector.md"},"headers":[],"relativePath":"sovereign-edge/epics/mobile/search-connector.md","filePath":"sovereign-edge/epics/mobile/search-connector.md"}'),r={name:"sovereign-edge/epics/mobile/search-connector.md"};function i(s,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-search-connector" tabindex="-1">Epic: Search Connector <a class="header-anchor" href="#epic-search-connector" aria-label="Permalink to &quot;Epic: Search Connector&quot;">​</a></h1><blockquote><p>The Search connector — the first real, non-test consumer of the <a href="./connector-framework.html">Connector Framework</a>, and the one connector that ships in the Phase 1 MVP.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Research 0001 left &quot;exact default search backend&quot; as an explicit open question, and it stayed open through implementation: a random public SearXNG instance turns out not to be a safe zero-config default — most disable JSON output, and at least one documented failure mode returns HTTP 200 with an HTML body where JSON was expected, which silently breaks rather than failing cleanly. Tavily is not zero-config either — it needs a paid key from every user. Neither made &quot;ship a hardcoded default&quot; the right call.</p><p>What shipped instead: <strong>one logical Search connector, two interchangeable providers, configured by the user on first use</strong> — a setup screen (Settings → Connectors → Search) where the user picks SearXNG (self-hosted or one they trust, plus its URL) or Tavily (plus their own API key). Nothing is pre-configured; that is the honest state, not a gap to hide. This absorbed what task 3.2 originally set out to do (see below) — &quot;configurable endpoint&quot; and &quot;no safe default exists&quot; turned out to be the same problem.</p><p>Both providers back the identical <code>web_search</code> tool — the model never knows or chooses which backend answers it, only the user does, in settings. Switching providers reuses task 2.2&#39;s permission machinery unmodified: a different provider means a different <code>permissions.network.origins</code>, which <code>needsRedecision()</code> already treats as requiring a fresh grant, because it is one.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-3-1-—-default-search-connector" tabindex="-1">✅ 3.1 — Default Search connector <a class="header-anchor" href="#✅-3-1-—-default-search-connector" aria-label="Permalink to &quot;✅ 3.1 — Default Search connector&quot;">​</a></h4><p><strong>Goal:</strong> A working Tier 1 connector that lets the model answer questions needing current web information — redefined during implementation from &quot;one connector with a hardcoded default&quot; to &quot;one connector, user-configured provider,&quot; per the Overview above.</p><p><strong>Deliverables:</strong></p><ul><li>Two manifests behind one connector id (<code>fs.sovereign.search</code>): <code>buildSearxngManifest(instanceUrl)</code> (<code>src/connectors/search/manifest.ts</code>) — a factory, since the origin is user-supplied — and a fully static <code>TAVILY_MANIFEST</code>, since only its credential varies and that already flows through the existing per-connector vault (task 2.2) with no manifest change needed.</li><li>A plain-JSON config store (<code>src/connectors/search/config.ts</code>) for the non-secret choice of provider (+ SearXNG URL), following the same secret-vs-not-secret split <code>grants.ts</code>/<code>vault.ts</code> already established in task 2.2.</li><li><code>SearchSetupScreen</code> (<code>src/settings/screens/</code>): provider picker, the matching field, validated through the real <code>validateManifest()</code> (task 2.1) before anything is saved, so a bad or cleartext URL is rejected the same way an author&#39;s mistake would be — no special-casing for user-supplied config.</li><li><code>ConnectorsScreen</code> and <code>ModelSessionProvider</code> both read the live config at call time rather than a static list, so &quot;configure once&quot; is immediately reflected everywhere without a second data path for Search specifically.</li></ul><p><strong>Dependencies:</strong> Connector Framework epic (2.1–2.5).</p><p><strong>Review checklist:</strong></p><ul><li>✅ With the connector permission denied, a search-requiring question is answered by explaining the connector isn&#39;t enabled, not by silently failing or hallucinating an answer.</li><li>✅ With permission granted, a real search round-trips and the reply cites that the Search connector was used.</li></ul><p><strong>The <code>https</code>-only rule was deliberately not relaxed for self-hosted SearXNG.</strong> <code>NSAllowsLocalNetworking</code> already anticipates a future connector (Sovereign Tasks, task 4.2) reaching something on the user&#39;s own LAN, which reads like it might need cleartext HTTP — but self-hosting SearXNG turned out not to be this project&#39;s concern beyond its own testing. The manifest validator (task 2.1) still requires <code>https</code> unconditionally, for every origin, with no private-address exception. Getting TLS in front of a self-hosted instance (a reverse proxy, even a self-signed one) is the user&#39;s responsibility, same as standing up the instance itself.</p><p><strong>Verified on-device against a real endpoint, with a real key, not just mocks — and against a real user&#39;s phone, not only a simulator.</strong> A local SearXNG instance (Docker, JSON output explicitly enabled, TLS terminated via a local Caddy proxy with its root CA trusted into the simulator) proved a full round trip end to end: a real request built from the manifest template, a real response mapped through <code>textFrom</code>, a real second-pass answer citing &quot;via Search (SearXNG)&quot;. Tavily&#39;s request shape was confirmed against the real <code>api.tavily.com</code> with a deliberately invalid placeholder key — a real <code>401</code>/<code>403</code> back (not a network or malformed-request error) proves the endpoint, method, and <code>Authorization</code> header shape are correct without ever handling the user&#39;s actual key, which stayed theirs to enter. The real key was later entered and exercised by the user themselves on their own physical iPhone, closing the one gap a simulator harness could not.</p><p><strong>Four real findings from that device verification, none visible from a green test suite:</strong></p><ul><li><strong>An ordinary connector result could exhaust the model&#39;s context outright, not just produce a worse answer.</strong> <code>generateWithConnectors</code> (<code>src/settings/connectorOrchestration.ts</code>) folded the connector&#39;s full result into the follow-up prompt with only <code>response.maxBytes</code> (task 2.4) as a cap — generous enough to protect against a misbehaving endpoint, not sized for a 2048-token context. A real SearXNG <code>results</code> array was large enough on its own to fail generation with &quot;Context is full.&quot; Fixed with a 2000-character budget on the connector&#39;s result specifically, independent of the network-level cap, which exists for a different threat.</li><li><strong><code>ConnectorsScreen</code> showed stale &quot;not set up&quot; state after a real, working save.</strong> It reads <code>readSearchConfig()</code> at render time, and React Navigation does not re-render a screen merely because it regained focus after <code>goBack()</code> — the save had genuinely worked; the screen just never looked again. Fixed with <code>useFocusEffect</code> triggering the same <code>refresh()</code> the grant/revoke flow already used. The existing reachability test only checked the screen could be navigated to once, not that it stayed correct after a full round trip through setup — a real user hit this within minutes of using the feature for real.</li><li><strong>There was no way back into setup once configured</strong>, only grant/revoke on whatever was already there — found when a real user needed to fix a mistyped key and had nowhere to go. Fixed with a second row, &quot;Change provider or key,&quot; that reaches <code>SearchSetupScreen</code> regardless of current grant state.</li><li><strong>The physical-device build itself surfaced two environment gaps worth recording</strong>, neither specific to this task&#39;s code but both blocking real verification: <code>xcodebuild -allowProvisioningUpdates</code> does not reliably create a first-time provisioning profile the way Xcode&#39;s own GUI does (a &quot;Try Again&quot; click in Signing &amp; Capabilities was needed); and a device build invoked directly via <code>xcodebuild</code> — bypassing <code>expo run:ios</code>&#39;s own wrapper — needs <code>REACT_NATIVE_PACKAGER_HOSTNAME</code> set explicitly to the Mac&#39;s LAN IP, since a physical device cannot resolve <code>localhost</code> to the build machine the way a simulator can.</li></ul><p><strong>A fifth finding, real but out of this task&#39;s scope: small-model tool-choice judgment is not just unreliable, it can be actively misleading.</strong> With a real connector finally in place, on-device testing surfaced cases beyond the &quot;calls a tool that wasn&#39;t needed&quot; cliff task 2.3 already documented — Qwen2.5 0.5B, offered the tool, sometimes answered in its own words instead (consistent with 2.3&#39;s finding) but at least once <strong>claimed to have searched when it had not</strong>, fabricating an answer with no <code>tool-call</code> decision behind it at all. The UI itself stays honest — no genuine tool call means no &quot;via Search&quot; tag — but a user who doesn&#39;t notice the missing tag is misled by the model&#39;s own words. <code>tool_choice: &#39;auto&#39;</code> asks a small model to make a judgment call it does not reliably make well, or honestly. Fixing this means removing the ambiguity rather than tuning around it — most plausibly an explicit Search mode (alongside Chat/Brainstorm/Fix grammar/Rewrite tone) where the mode selection itself is the decision, not something asked of the model at all. Scoped as its own follow-up task, not folded into 3.1.</p><hr><h4 id="✅-3-2-—-configurable-meta-search-endpoint" tabindex="-1">✅ 3.2 — Configurable meta-search endpoint <a class="header-anchor" href="#✅-3-2-—-configurable-meta-search-endpoint" aria-label="Permalink to &quot;✅ 3.2 — Configurable meta-search endpoint&quot;">​</a></h4><p><strong>Merged into 3.1.</strong> This task&#39;s own goal — &quot;avoid hardcoding a single company&#39;s search API, let the endpoint be user-configurable&quot; — is exactly what 3.1 shipped, for the reason explained in the Overview: neither provider turned out to be safely zero-config, so &quot;configurable&quot; stopped being an enhancement over a working default and became the only honest way to ship this at all. <code>SearchSetupScreen</code> <strong>is</strong> this task&#39;s deliverable. Nothing separate remains to build; kept as its own epic task line rather than deleted, because the id is permanent and the roadmap should show why the slot closed rather than simply vanish.</p><hr><h4 id="✅-3-3-—-explicit-search-mode" tabindex="-1">✅ 3.3 — Explicit Search mode <a class="header-anchor" href="#✅-3-3-—-explicit-search-mode" aria-label="Permalink to &quot;✅ 3.3 — Explicit Search mode&quot;">​</a></h4><p><strong>Goal:</strong> Remove the ambiguity <code>tool_choice: &#39;auto&#39;</code> leaves in a small model&#39;s hands, per 3.1&#39;s fifth finding — a mode where the user&#39;s own selection is the decision, not a judgment call asked of the model at all.</p><p><strong>Deliverables:</strong></p><ul><li>A new <code>&#39;search&#39;</code> mode (<code>src/chat/modes/modes.ts</code>), alongside Chat/ Brainstorm/Fix grammar/Rewrite tone, selected the same way as any other mode via the existing mode bar — no new UI surface needed.</li><li><code>tool_choice: &#39;required&#39;</code> threaded end to end: <code>routeMessage</code> (task 2.3) gains a caller-specified <code>toolChoice</code> on <code>RouteOptions</code> (default <code>&#39;auto&#39;</code>, unchanged for every existing caller); <code>generateWithConnectors</code> (task 2.5) gains the same on <code>ConnectorOrchestrationRequest</code>; <code>ChatSessionContext</code>&#39;s <code>GenerateRequest</code> replaces the old <code>allowConnectors: boolean</code> with a <code>connectorMode: &#39;off&#39; | &#39;auto&#39; | &#39;required&#39;</code> tri-state, since a boolean cannot also carry &quot;and skip asking the model&quot; without a fourth, invalid combination existing in the type. <code>ChatScreen</code> maps mode → <code>connectorMode</code>: <code>&#39;plain&#39;</code> → <code>&#39;auto&#39;</code>, <code>&#39;search&#39;</code> → <code>&#39;required&#39;</code>, everything else → <code>&#39;off&#39;</code>.</li><li>Two failure modes specific to <code>&#39;required&#39;</code>, handled explicitly rather than falling through to <code>&#39;auto&#39;</code>&#39;s existing (correct, for <code>&#39;auto&#39;</code>) behavior: no connector configured at all (a plain instruction to go configure one, no generation attempted — forcing a tool call with nothing to call is nonsensical) and a model that cannot call tools (a clear &quot;this model can&#39;t use connectors&quot; message, not the model&#39;s own prose about lacking real-time access, which in a mode the user explicitly chose <em>because</em> they wanted a real search would otherwise read as a search that was quietly skipped rather than a capability gap).</li></ul><p><strong>Dependencies:</strong> Task 3.1 (the connector this mode forces), task 2.3 (<code>routeMessage</code>), task 2.5 (<code>generateWithConnectors</code>).</p><p><strong>Review checklist:</strong></p><ul><li>✅ Every message sent in Search mode either genuinely calls the connector or explains clearly why it could not (not configured, not granted, or the model can&#39;t call tools) — never a plain, unlabelled answer standing in for a search that didn&#39;t happen.</li><li>✅ The other modes are unaffected: Chat still lets the model decide, and the writing-assist modes still never reach a connector at all.</li></ul><p><strong>Verified on the user&#39;s own physical device</strong> (Metro Fast Refresh — pure TypeScript, no native change, no rebuild needed): the Search chip appears, selecting it and asking a question forces a real connector call, and the banner names the mode the same way a writing-assist mode&#39;s does — which needed its own small fix, since the banner&#39;s visibility was keyed off <code>mode.systemPrompt</code> being non-null, a proxy that happened to hold for every mode that existed before this one. Search has no system prompt at all — its effect is entirely the forced <code>connectorMode</code>, not a model instruction — so the condition was changed to <code>mode.id !== DEFAULT_MODE_ID</code>, the thing the banner was actually trying to express.</p><p><strong>Left open:</strong> whether <code>llama.rn</code>/the underlying grammar engine honors <code>tool_choice: &#39;required&#39;</code> as strictly as <code>&#39;auto&#39;</code> was already confirmed to work (research 0004&#39;s finding) has not been independently stress-tested the way <code>&#39;auto&#39;</code> was across many device runs in tasks 2.3 and 3.1 — the on-device check above confirms it works for the cases tried, not that it is airtight against every phrasing. Worth a closer look if a <code>&#39;required&#39;</code> request is ever observed resolving to <code>answered</code> rather than <code>tool-call</code> or <code>blocked</code>.</p><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./connector-framework.html">Connector Framework</a></li></ul>',34)])])}const p=o(r,[["render",i]]);export{g as __pageData,p as default};
